-- Run once after 01_navar_schema.sql.
-- New beacon and battery codes are generated by the backend. This migration
-- only repairs schema and legacy rows; it does not generate new codes.
ALTER TABLE BEACON ADD COLUMN IF NOT EXISTS FLOOR_ID INTEGER;
ALTER TABLE BATTERY ADD COLUMN IF NOT EXISTS BATTERY_CODE VARCHAR(50);

-- Fill codes only for legacy battery rows that predate BATTERY_CODE.
UPDATE BATTERY
SET BATTERY_CODE = CONCAT('BAT-', LPAD(BATTERY_ID::TEXT, 4, '0'))
WHERE BATTERY_CODE IS NULL;

-- Legacy beacons did not store a floor. Assign each one to its mall's first
-- floor so the required foreign key can be applied safely.
UPDATE BEACON beacon
SET FLOOR_ID = floors.FLOOR_ID
FROM (
	SELECT DISTINCT ON (MALL_ID) MALL_ID, FLOOR_ID
	FROM FLOOR
	ORDER BY MALL_ID, FLOOR_NUM, FLOOR_ID
) floors
WHERE beacon.MALL_ID = floors.MALL_ID
  AND beacon.FLOOR_ID IS NULL;

ALTER TABLE BATTERY ALTER COLUMN BATTERY_CODE SET NOT NULL;
ALTER TABLE BEACON ALTER COLUMN FLOOR_ID SET NOT NULL;

DO $$
BEGIN
	IF NOT EXISTS (
		SELECT 1 FROM pg_constraint WHERE conname = 'fk_beacon_floor_id'
	) THEN
		ALTER TABLE BEACON
		ADD CONSTRAINT fk_beacon_floor_id
		FOREIGN KEY (FLOOR_ID) REFERENCES FLOOR(FLOOR_ID);
	END IF;
END $$;

CREATE UNIQUE INDEX IF NOT EXISTS uq_battery_code ON BATTERY(BATTERY_CODE);
